/* DX brand “Mangrove” — made with the DX theme builder. Use: <html data-brand="mangrove" data-density="comfortable"> */
:root[data-brand="mangrove"], [data-brand="mangrove"] {
  --ds-brand-primary-50: #f2f6f3;
  --ds-brand-accent-50: #fffbeb;
  --ds-brand-neutral-50: #fafaf9;
  --ds-brand-primary-100: #e2ebe4;
  --ds-brand-accent-100: #fef3c7;
  --ds-brand-neutral-100: #f5f5f4;
  --ds-brand-primary-200: #ccddd1;
  --ds-brand-accent-200: #fde68a;
  --ds-brand-neutral-200: #e7e5e4;
  --ds-brand-primary-300: #abcab4;
  --ds-brand-accent-300: #fcd34d;
  --ds-brand-neutral-300: #d6d3d1;
  --ds-brand-primary-400: #7eae8d;
  --ds-brand-accent-400: #fbbf24;
  --ds-brand-neutral-400: #a8a29e;
  --ds-brand-primary-500: #57976e;
  --ds-brand-accent-500: #f59e0b;
  --ds-brand-neutral-500: #78716c;
  --ds-brand-primary-600: #2f7d4f;
  --ds-brand-accent-600: #d97706;
  --ds-brand-neutral-600: #57534e;
  --ds-brand-primary-700: #227144;
  --ds-brand-accent-700: #b45309;
  --ds-brand-neutral-700: #44403c;
  --ds-brand-primary-800: #1f5c38;
  --ds-brand-accent-800: #92400e;
  --ds-brand-neutral-800: #292524;
  --ds-brand-primary-900: #244c33;
  --ds-brand-accent-900: #78350f;
  --ds-brand-neutral-900: #1c1917;
  --ds-brand-primary-950: #192f21;
  --ds-brand-accent-950: #451a03;
  --ds-brand-neutral-950: #0c0a09;
  --ds-brand-role-solid: #2f7d4f;
  --ds-brand-role-solid-hover: #227144;
  --ds-brand-role-solid-pressed: #1f5c38;
  --ds-brand-role-on-solid: #ffffff;
  --ds-brand-role-solid-hc: #1f5c38;
  --ds-brand-role-solid-hc-hover: #244c33;
  --ds-brand-role-on-solid-hc: #ffffff;
  --ds-brand-role-focus: #2f7d4f;
  --ds-font-family-heading: "Plus Jakarta Sans", ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;
  --ds-font-family-body: "Plus Jakarta Sans", ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;
  --ds-font-family-mono: "Roboto Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  --ds-font-weight-heading-semibold: 600;
  --ds-font-weight-heading-bold: 700;
  --ds-font-weight-body-regular: 400;
  --ds-font-weight-body-medium: 500;
  --ds-font-weight-mono-regular: 400;
  --ds-shape-radius-control: 12px;
  --ds-shape-radius-container: 16px;
}

